export const questionBank = [
  // Matemática
  { id: "mat-f-1", subject: "matematica", category: "MATEMÁTICA", difficulty: "facil", text: "Uma biblioteca comunitária recebeu 120 livros para ampliar o acervo. A equipe decidiu organizar 25% desse lote em uma estante dedicada a obras de ciências, deixando o restante para outras seções. Quantos livros foram destinados à estante de ciências?", options: ["20", "25", "30", "35"], correct: 2, explanation: "25% de 120 é 0,25 × 120 = 30.", year: null, examQuestion: null },
  { id: "mat-m-1", subject: "matematica", category: "MATEMÁTICA", difficulty: "medio", text: "Uma escola monitora a água de um reservatório que estava cheio e continha 240 litros. Durante uma atividade, foram utilizados 3/8 do volume inicial. Sem considerar reposição ou perdas adicionais, quantos litros ainda restaram no reservatório?", options: ["90 L", "120 L", "150 L", "180 L"], correct: 2, explanation: "3/8 de 240 são 90 L; restam 240 − 90 = 150 L.", year: null, examQuestion: null },
  { id: "mat-d-1", subject: "matematica", category: "MATEMÁTICA", difficulty: "dificil", text: "Em um modelo que relaciona o tempo de treino x ao desempenho f(x), uma equipe ajustou uma função afim f(x)=ax+b usando duas medições: f(2)=7 e f(5)=16. Supondo que a relação permaneça linear, qual valor o modelo prevê para f(0)?", options: ["−1", "1", "3", "4"], correct: 1, explanation: "A inclinação é (16−7)/(5−2)=3. Como 7=3·2+b, temos b=1; portanto f(0)=1.", year: null, examQuestion: null },
  // Física
  { id: "fis-f-1", subject: "fisica", category: "FÍSICA", difficulty: "facil", text: "Durante uma aula sobre deslocamento, uma bicicleta percorre 12 km em exatamente 1 hora e mantém velocidade constante durante todo o trajeto. Desconsiderando paradas e variações de ritmo, qual é a velocidade média desenvolvida pelo ciclista?", options: ["6 km/h", "10 km/h", "12 km/h", "24 km/h"], correct: 2, explanation: "A velocidade média é distância dividida pelo tempo: 12 km ÷ 1 h = 12 km/h.", year: null, examQuestion: null },
  { id: "fis-m-1", subject: "fisica", category: "FÍSICA", difficulty: "medio", text: "Em um experimento, um carrinho de massa igual a 2 kg recebe uma força resultante horizontal de 10 N. Desprezando o atrito e considerando a massa constante, a turma aplica a segunda lei de Newton para prever o movimento. Qual aceleração o carrinho adquire?", options: ["2 m/s²", "5 m/s²", "10 m/s²", "20 m/s²"], correct: 1, explanation: "Pela segunda lei de Newton, a = F/m = 10/2 = 5 m/s².", year: null, examQuestion: null },
  { id: "fis-d-1", subject: "fisica", category: "FÍSICA", difficulty: "dificil", text: "Um circuito de teste utiliza um resistor ôhmico de 6 Ω conectado a uma fonte ideal que mantém uma diferença de potencial de 12 V. Após calcular a corrente elétrica, um estudante precisa determinar a taxa de transformação de energia no resistor. Qual potência elétrica é dissipada?", options: ["12 W", "18 W", "24 W", "72 W"], correct: 2, explanation: "P=V²/R; portanto, 12²/6 = 24 W.", year: null, examQuestion: null },
  // Química
  { id: "qui-f-1", subject: "quimica", category: "QUÍMICA", difficulty: "facil", text: "Em uma atividade de tratamento de água, uma mistura contém areia sólida e água líquida. A equipe precisa separar os componentes usando uma barreira que permita a passagem do líquido, mas retenha as partículas sólidas. Qual método de separação é adequado?", options: ["Filtração", "Destilação", "Cromatografia", "Decantação fracionada"], correct: 0, explanation: "Na filtração, o sólido fica retido no filtro e o líquido atravessa seus poros.", year: null, examQuestion: null },
  { id: "qui-m-1", subject: "quimica", category: "QUÍMICA", difficulty: "medio", text: "Uma análise de laboratório separou uma amostra pura de água com massa de 18 g. Para relacionar essa massa à quantidade de partículas, considere a massa molar da água H₂O igual a 18 g/mol. Quantos mols de água há na amostra?", options: ["0,5 mol", "1 mol", "2 mol", "18 mol"], correct: 1, explanation: "n=m/M=18/18=1 mol.", year: null, examQuestion: null },
  { id: "qui-d-1", subject: "quimica", category: "QUÍMICA", difficulty: "dificil", text: "Uma solução aquosa de volume inicial igual a 100 mL apresenta concentração de 2 mol/L. Em seguida, adiciona-se solvente até que o volume final alcance 400 mL, sem perda de soluto. Qual é a concentração molar da solução após a diluição?", options: ["0,25 mol/L", "0,5 mol/L", "1 mol/L", "8 mol/L"], correct: 1, explanation: "Na diluição C₁V₁=C₂V₂. C₂=(2×100)/400=0,5 mol/L.", year: null, examQuestion: null },
  // Biologia
  { id: "bio-f-1", subject: "biologia", category: "BIOLOGIA", difficulty: "facil", text: "Ao observar células vegetais e animais ao microscópio, uma estudante identifica estruturas que armazenam e protegem grande parte das informações hereditárias. Embora existam exceções e DNA também esteja em outras organelas, qual estrutura abriga a maior parte do material genético em células eucarióticas?", options: ["Ribossomo", "Núcleo", "Lisossomo", "Membrana plasmática"], correct: 1, explanation: "O núcleo abriga a maior parte do DNA das células eucarióticas.", year: null, examQuestion: null },
  { id: "bio-m-1", subject: "biologia", category: "BIOLOGIA", difficulty: "medio", text: "Em um ecossistema, plantas e algas formam a base de muitas cadeias alimentares. Elas não obtêm toda a matéria orgânica consumindo outros seres: captam energia luminosa e a utilizam em reações que sustentam os níveis tróficos seguintes. Qual função dos produtores explica esse papel ecológico?", options: ["converter energia luminosa em energia química", "decompor todos os minerais", "consumir apenas outros produtores", "impedir o fluxo de energia"], correct: 0, explanation: "Organismos produtores, como plantas, realizam fotossíntese e introduzem energia na cadeia.", year: null, examQuestion: null },
  { id: "bio-d-1", subject: "biologia", category: "BIOLOGIA", difficulty: "dificil", text: "Em uma população idealizada, uma pesquisa genética identificou que 9% dos indivíduos apresentam uma característica determinada por um alelo recessivo em homozigose. Admitindo acasalamento ao acaso e equilíbrio de Hardy-Weinberg, qual é a frequência desse alelo recessivo na população?", options: ["0,09", "0,18", "0,30", "0,91"], correct: 2, explanation: "A frequência de homozigotos recessivos é q²=0,09; logo q=√0,09=0,30.", year: null, examQuestion: null },
  // Filosofia
  { id: "fil-f-1", subject: "filosofia", category: "FILOSOFIA", difficulty: "facil", text: "Em uma conversa sobre regras escolares, uma estudante não aceita uma afirmação apenas porque muitas pessoas a repetem. Ela pede justificativas, compara razões e considera evidências antes de formar sua opinião. Essa postura se aproxima principalmente de qual atitude filosófica?", options: ["investigação crítica", "dogmatismo", "tradição irrefletida", "relativismo absoluto"], correct: 0, explanation: "A investigação crítica examina argumentos e razões em vez de aceitar uma ideia sem análise.", year: null, examQuestion: null },
  { id: "fil-m-1", subject: "filosofia", category: "FILOSOFIA", difficulty: "medio", text: "Nos diálogos associados a Sócrates, o interlocutor é conduzido por perguntas a explicitar o que entende por justiça, coragem ou conhecimento. Quando suas respostas entram em conflito, a conversa permite rever crenças e buscar definições mais consistentes. Qual era a finalidade central desse método?", options: ["impor uma resposta pela força", "examinar ideias e reconhecer contradições", "substituir toda reflexão por mitos", "evitar discutir definições"], correct: 1, explanation: "O método socrático usa perguntas para examinar crenças e tornar explícitas suas inconsistências.", year: null, examQuestion: null },
  { id: "fil-d-1", subject: "filosofia", category: "FILOSOFIA", difficulty: "dificil", text: "Uma teoria considera legítima uma norma quando todos os afetados poderiam aceitá-la em um diálogo livre e racional. Qual princípio está mais próximo dessa ideia?", options: ["validade pelo consenso discursivo", "verdade definida pela autoridade", "utilidade privada imediata", "obediência por hábito"], correct: 0, explanation: "A ética discursiva relaciona a legitimidade das normas à possibilidade de justificá-las em diálogo inclusivo.", year: null, examQuestion: null },
  // História
  { id: "his-f-1", subject: "historia", category: "HISTÓRIA", difficulty: "facil", text: "Em 13 de maio de 1888, foi promulgada uma lei que encerrou juridicamente a escravidão no Brasil. A medida foi resultado de décadas de resistência de pessoas escravizadas e de mobilização abolicionista, embora não tenha garantido igualdade social. O que essa lei determinou formalmente?", options: ["o fim legal da escravidão", "a proclamação da República", "a criação do voto secreto", "a independência do Brasil"], correct: 0, explanation: "A Lei Áurea aboliu juridicamente a escravidão no Brasil em 13 de maio de 1888.", year: null, examQuestion: null },
  { id: "his-m-1", subject: "historia", category: "HISTÓRIA", difficulty: "medio", text: "A industrialização iniciada na Inglaterra transformou formas de produção, relações de trabalho e organização do espaço. A concentração de fábricas atraiu trabalhadores para cidades, que cresceram rapidamente e enfrentaram novos desafios de moradia e infraestrutura. Qual consequência histórica está associada a esse processo?", options: ["a expansão do trabalho fabril e da urbanização", "o desaparecimento imediato das desigualdades", "o retorno geral à produção artesanal doméstica", "o fim do uso de máquinas"], correct: 0, explanation: "A industrialização concentrou a produção em fábricas e acelerou a urbanização.", year: null, examQuestion: null },
  { id: "his-d-1", subject: "historia", category: "HISTÓRIA", difficulty: "dificil", text: "No período posterior à Segunda Guerra Mundial, os Estados Unidos financiaram alianças e programas de assistência a países que consideravam estratégicos, enquanto competiam com a União Soviética por influência política. Qual objetivo principal orientava a política estadunidense de contenção durante a Guerra Fria?", options: ["impedir a expansão da influência soviética", "restaurar os impérios coloniais europeus", "abolir a ONU", "unificar politicamente toda a Europa"], correct: 0, explanation: "A contenção procurava limitar a expansão do socialismo soviético e de sua influência geopolítica.", year: null, examQuestion: null },
  // Geografia
  { id: "geo-f-1", subject: "geografia", category: "GEOGRAFIA", difficulty: "facil", text: "Uma equipe produz a planta de um bairro para localizar ruas, praças e pontos de ônibus. Como o espaço representado é relativamente pequeno, o mapa pode mostrar muitos detalhes de cada elemento. O que caracteriza uma representação cartográfica em grande escala, como essa planta?", options: ["uma área menor com mais detalhes", "uma área continental com poucos detalhes", "todo o planeta sem distorções", "somente elementos climáticos"], correct: 0, explanation: "A grande escala mostra uma área relativamente pequena com maior nível de detalhe.", year: null, examQuestion: null },
  { id: "geo-m-1", subject: "geografia", category: "GEOGRAFIA", difficulty: "medio", text: "Uma cidade recebe novos moradores, mas a construção de moradias, redes de saneamento e linhas de transporte não acompanha o mesmo ritmo. Em algumas áreas, longos deslocamentos e habitação precária tornam-se mais comuns. Qual pressão urbana pode ser ampliada por esse crescimento sem infraestrutura equivalente?", options: ["a pressão sobre moradia e transporte", "a disponibilidade automática de saneamento", "a redução de deslocamentos", "a eliminação da segregação socioespacial"], correct: 0, explanation: "O crescimento urbano desigual pode sobrecarregar habitação, saneamento, transporte e serviços públicos.", year: null, examQuestion: null },
  { id: "geo-d-1", subject: "geografia", category: "GEOGRAFIA", difficulty: "dificil", text: "Um telefone pode ser projetado em um país, utilizar minerais extraídos em outro, receber componentes fabricados em diferentes regiões e ser montado perto do mercado consumidor. A coordenação dessas etapas depende de logística, comércio e decisões de empresas transnacionais. O que essa organização espacial da produção evidencia?", options: ["a fragmentação internacional das cadeias produtivas", "o fim do comércio internacional", "a autossuficiência de todas as economias", "a redução das redes logísticas"], correct: 0, explanation: "A globalização produtiva distribui etapas de produção entre diferentes territórios conectados por redes comerciais e logísticas.", year: null, examQuestion: null },
  // Educação Física
  { id: "edf-f-1", subject: "educacao-fisica", category: "EDUCAÇÃO FÍSICA", difficulty: "facil", text: "Durante uma avaliação de movimento, uma estudante realiza alongamentos que aumentam o ângulo de movimento de uma articulação, respeitando seus limites e sem buscar velocidade ou força máxima. Qual capacidade física está mais diretamente relacionada à amplitude dos movimentos articulares?", options: ["Flexibilidade", "Resistência", "Velocidade", "Força máxima"], correct: 0, explanation: "Flexibilidade é a capacidade relacionada à amplitude dos movimentos articulares.", year: null, examQuestion: null },
  { id: "edf-m-1", subject: "educacao-fisica", category: "EDUCAÇÃO FÍSICA", difficulty: "medio", text: "Em uma caminhada contínua, os músculos precisam receber oxigênio e nutrientes e eliminar parte dos produtos do metabolismo. Para isso, sangue circula entre pulmões, coração e tecidos ativos durante o esforço. Qual sistema do corpo tem papel central nesse transporte de oxigênio até os músculos?", options: ["Cardiovascular", "Digestório", "Tegumentar", "Excretor"], correct: 0, explanation: "O sistema cardiovascular transporta oxigênio pelo sangue até os tecidos ativos.", year: null, examQuestion: null },
  { id: "edf-d-1", subject: "educacao-fisica", category: "EDUCAÇÃO FÍSICA", difficulty: "dificil", text: "Durante uma aula de esporte, a professora percebe que uma regra impede parte da turma de participar plenamente. Ela modifica dimensões do espaço e oferece opções de material, preservando o objetivo coletivo da atividade. Qual finalidade pedagógica deve orientar principalmente essas adaptações?", options: ["ampliar acesso e participação com equidade", "eliminar a aprendizagem motora", "garantir vantagem competitiva a uma pessoa", "substituir toda atividade por avaliação escrita"], correct: 0, explanation: "A adaptação inclusiva reduz barreiras e permite participação significativa, preservando objetivos de aprendizagem.", year: null, examQuestion: null },
  // Interdisciplinar
  { id: "int-f-1", subject: "interdisciplinar", category: "INTERDISCIPLINAR", difficulty: "facil", text: "Em uma ação de revitalização, estudantes distribuíram mudas igualmente entre quatro canteiros de uma praça. Cada canteiro recebeu seis mudas, e nenhuma foi reservada para outro local. Quantas mudas foram plantadas ao todo nessa atividade de educação ambiental?", options: ["10", "18", "24", "30"], correct: 2, explanation: "São 4 grupos de 6 mudas: 4 × 6 = 24.", year: null, examQuestion: null },
  { id: "int-m-1", subject: "interdisciplinar", category: "INTERDISCIPLINAR", difficulty: "medio", text: "Uma estação meteorológica escolar registrou 18 °C às 6 horas e 27 °C às 14 horas do mesmo dia. Considerando apenas a diferença entre as duas medições, sem discutir outras variações ao longo do período, de quantos graus Celsius foi a variação da temperatura?", options: ["7 °C", "8 °C", "9 °C", "45 °C"], correct: 2, explanation: "A variação é 27 − 18 = 9 °C.", year: null, examQuestion: null },
  { id: "int-d-1", subject: "interdisciplinar", category: "INTERDISCIPLINAR", difficulty: "dificil", text: "Uma região registrou consumo anual de 1.200 m³ de água e, após medidas de reuso e redução de perdas, passou a consumir 900 m³. Para avaliar o resultado, a equipe compara a quantidade economizada com o consumo original. Qual foi a redução percentual em relação ao valor inicial?", options: ["15%", "20%", "25%", "30%"], correct: 2, explanation: "A redução foi 300 m³; 300/1.200 × 100 = 25%.", year: null, examQuestion: null },
  // Novas questões autorais — Matemática
  { id: "mat-f-2", subject: "matematica", category: "MATEMÁTICA", difficulty: "facil", text: "Uma equipe de estudantes vai pintar um mural retangular para uma campanha da escola. O painel tem 8 m de comprimento e 5 m de altura, e a tinta necessária depende da área total coberta. Qual é a área desse mural?", options: ["13 m²", "26 m²", "40 m²", "80 m²"], correct: 2, explanation: "A área do retângulo é comprimento × altura: 8 × 5 = 40 m².", year: null, examQuestion: null },
  { id: "mat-m-2", subject: "matematica", category: "MATEMÁTICA", difficulty: "medio", text: "Em uma atividade de probabilidade, uma caixa contém cinco cartões indistinguíveis ao toque: três verdes e dois amarelos. Um cartão será retirado ao acaso, sem olhar, e todos têm a mesma chance de serem escolhidos. Qual é a probabilidade de retirar um cartão amarelo?", options: ["20%", "40%", "50%", "60%"], correct: 1, explanation: "Há 2 cartões amarelos em 5; 2/5 = 0,4 = 40%.", year: null, examQuestion: null },
  { id: "mat-d-2", subject: "matematica", category: "MATEMÁTICA", difficulty: "dificil", text: "Um modelo matemático para uma trajetória é descrito pela equação quadrática x² − 5x + 6 = 0. Para identificar os instantes em que a trajetória cruza uma referência, é preciso determinar as raízes e compará-las. Sabendo que ambas são positivas, qual é a menor raiz?", options: ["1", "2", "3", "6"], correct: 1, explanation: "A expressão fatorada é (x − 2)(x − 3)=0; as raízes são 2 e 3, então a menor é 2.", year: null, examQuestion: null },
  // Novas questões autorais — Física
  { id: "fis-f-2", subject: "fisica", category: "FÍSICA", difficulty: "facil", text: "Em uma demonstração de laboratório, um bloco regular possui massa de 3 kg e ocupa um volume de 1 m³. A turma usa essas medidas para comparar materiais e calcular a quantidade de massa por unidade de volume. Qual é a densidade média desse bloco?", options: ["1 kg/m³", "2 kg/m³", "3 kg/m³", "4 kg/m³"], correct: 2, explanation: "Densidade é massa dividida pelo volume: 3 kg ÷ 1 m³ = 3 kg/m³.", year: null, examQuestion: null },
  { id: "fis-m-2", subject: "fisica", category: "FÍSICA", difficulty: "medio", text: "Um carrinho de laboratório é puxado por uma força constante de 20 N e se desloca 3 m em linha reta na mesma direção e no mesmo sentido da força. Desconsiderando outras forças e considerando o deslocamento informado, qual trabalho é realizado por essa força?", options: ["23 J", "60 J", "100 J", "600 J"], correct: 1, explanation: "Para força paralela ao deslocamento, W=F·d=20×3=60 J.", year: null, examQuestion: null },
  { id: "fis-d-2", subject: "fisica", category: "FÍSICA", difficulty: "dificil", text: "Durante uma atividade sobre movimento vertical, um objeto é solto do repouso e cai próximo à superfície da Terra. Despreze a resistência do ar e adote g=10 m/s² constante. Qual será o módulo da velocidade do objeto após 3 segundos de queda?", options: ["10 m/s", "20 m/s", "30 m/s", "90 m/s"], correct: 2, explanation: "Na queda livre a partir do repouso, v=g·t=10×3=30 m/s.", year: null, examQuestion: null },
  // Novas questões autorais — Química
  { id: "qui-f-2", subject: "quimica", category: "QUÍMICA", difficulty: "facil", text: "A tabela periódica organiza os elementos químicos de acordo com propriedades relacionadas à estrutura de seus átomos. Uma amostra contém átomos neutros de oxigênio, cujo número atômico é 8. Considerando a definição de número atômico, quantos prótons existem no núcleo de cada átomo?", options: ["6", "7", "8", "16"], correct: 2, explanation: "O número atômico corresponde ao número de prótons; para o oxigênio, é 8.", year: null, examQuestion: null },
  { id: "qui-m-2", subject: "quimica", category: "QUÍMICA", difficulty: "medio", text: "Uma equipe analisa uma solução aquosa e mede pH igual a 3, indicando caráter ácido. Para relacionar essa medida à concentração de íons em uma aproximação usual, aplica a definição pH = −log[H⁺]. Qual é a concentração aproximada de íons H⁺?", options: ["10⁻¹ mol/L", "10⁻³ mol/L", "10³ mol/L", "3 mol/L"], correct: 1, explanation: "pH = −log[H⁺]; assim, pH 3 corresponde a [H⁺]=10⁻³ mol/L.", year: null, examQuestion: null },
  { id: "qui-d-2", subject: "quimica", category: "QUÍMICA", difficulty: "dificil", text: "Na reação 2 H₂ + O₂ → 2 H₂O, quantos mols de água podem ser formados a partir de 4 mol de H₂ com O₂ em excesso?", options: ["2 mol", "3 mol", "4 mol", "8 mol"], correct: 2, explanation: "A proporção entre H₂ e H₂O é 2:2, ou seja, 1:1; 4 mol de H₂ formam 4 mol de H₂O.", year: null, examQuestion: null },
  // Novas questões autorais — Biologia
  { id: "bio-f-2", subject: "biologia", category: "BIOLOGIA", difficulty: "facil", text: "Em uma estufa, plantas recebem água e luz e realizam processos que produzem açúcares usados no crescimento. Para isso, elas também utilizam uma substância gasosa presente no ar e liberam oxigênio. Qual gás é absorvido pelas plantas durante a fotossíntese?", options: ["Dióxido de carbono", "Oxigênio", "Hidrogênio", "Nitrogênio"], correct: 0, explanation: "Na fotossíntese, as plantas utilizam dióxido de carbono e água para produzir matéria orgânica, liberando oxigênio.", year: null, examQuestion: null },
  { id: "bio-m-2", subject: "biologia", category: "BIOLOGIA", difficulty: "medio", text: "Durante a renovação de um tecido, uma célula somática duplica seu material genético e depois se divide. O processo mantém o número de cromossomos característico da espécie nas células resultantes, diferentemente da formação de gametas. Qual resultado é esperado após a mitose?", options: ["quatro células haploides", "duas células com conjunto cromossômico equivalente ao da célula inicial", "uma célula sem material genético", "duas células sempre geneticamente diferentes"], correct: 1, explanation: "A mitose produz duas células-filhas com o mesmo número de cromossomos da célula que iniciou a divisão.", year: null, examQuestion: null },
  { id: "bio-d-2", subject: "biologia", category: "BIOLOGIA", difficulty: "dificil", text: "No cruzamento entre dois indivíduos Aa, em que A é dominante completo sobre a, qual é a probabilidade de um descendente apresentar o fenótipo recessivo?", options: ["0%", "25%", "50%", "75%"], correct: 1, explanation: "Aa × Aa produz proporção genotípica 1 AA : 2 Aa : 1 aa; o fenótipo recessivo aparece em aa, isto é, 1/4 ou 25%.", year: null, examQuestion: null },
  // Novas questões autorais — Filosofia
  { id: "fil-f-2", subject: "filosofia", category: "FILOSOFIA", difficulty: "facil", text: "Ao analisar escolhas cotidianas, uma estudante observa que coragem não significa agir sem pensar nem evitar todo risco. Em Aristóteles, a virtude envolve uma disposição formada pelo hábito e orientada pela razão diante das circunstâncias. Qual ideia resume melhor essa concepção ética?", options: ["uma disposição equilibrada entre excessos", "obediência cega a qualquer ordem", "busca exclusiva de riqueza", "rejeição de toda deliberação"], correct: 0, explanation: "A virtude ética é associada ao justo meio, definido pela razão em relação às circunstâncias.", year: null, examQuestion: null },
  { id: "fil-m-2", subject: "filosofia", category: "FILOSOFIA", difficulty: "medio", text: "No pensamento de Thomas Hobbes, a ausência de uma autoridade comum poderia deixar indivíduos sujeitos à insegurança e a conflitos constantes. Para tornar possível a convivência, eles estabelecem um pacto e reconhecem um poder capaz de fazer cumprir regras. Qual é a finalidade política central desse pacto?", options: ["organizar a vida comum e reduzir a insegurança", "eliminar toda forma de autoridade", "restaurar a sociedade feudal", "impedir qualquer lei comum"], correct: 0, explanation: "Para Hobbes, o pacto institui uma autoridade comum capaz de conter conflitos e garantir segurança.", year: null, examQuestion: null },
  { id: "fil-d-2", subject: "filosofia", category: "FILOSOFIA", difficulty: "dificil", text: "Uma pessoa pensa em mentir para obter vantagem, mas avalia se a regra que orienta sua ação poderia valer para todas as pessoas em situações semelhantes. Na filosofia moral de Kant, essa análise não se reduz às consequências imediatas para o agente. Qual critério deve ser aplicado à máxima da ação?", options: ["garantir vantagem pessoal em cada caso", "ser aceita somente por quem detém poder", "ser universalizada sem contradição", "produzir prazer imediato para o agente"], correct: 2, explanation: "O imperativo categórico orienta a agir segundo máximas que possam valer como lei universal.", year: null, examQuestion: null },
  // Novas questões autorais — História
  { id: "his-f-2", subject: "historia", category: "HISTÓRIA", difficulty: "facil", text: "No início do século XIX, mudanças políticas na América portuguesa aceleraram a separação entre Brasil e Portugal. Um marco desse processo foi proclamado por Dom Pedro em setembro de 1822 e passou a ser celebrado como data nacional. Em que ano ocorreu a Independência do Brasil?", options: ["1808", "1822", "1888", "1889"], correct: 1, explanation: "A Independência foi proclamada em 1822, durante o processo de separação política de Portugal.", year: null, examQuestion: null },
  { id: "his-m-2", subject: "historia", category: "HISTÓRIA", difficulty: "medio", text: "A crise política de 1930 levou Getúlio Vargas ao poder e alterou a organização da República brasileira. O movimento encerrou a ordem dominada por oligarquias estaduais conhecida como Primeira República, embora as disputas políticas tenham continuado em novas formas. Qual período foi encerrado naquele processo?", options: ["Primeira República", "Era Vargas", "ditadura do Estado Novo", "República Nova de 1946"], correct: 0, explanation: "O movimento de 1930 encerrou a chamada Primeira República e iniciou um novo período político sob Vargas.", year: null, examQuestion: null },
  { id: "his-d-2", subject: "historia", category: "HISTÓRIA", difficulty: "dificil", text: "Iniciada em 1791 na colônia francesa de Saint-Domingue, a revolução envolveu pessoas escravizadas, libertas e outros grupos em disputas que transformaram profundamente a ordem colonial. O processo culminou na criação de um Estado independente em 1804. Que dominação foi combatida junto com o sistema escravista?", options: ["a industrialização inglesa", "a unificação italiana", "a dominação colonial francesa", "a expansão do Império Bizantino"], correct: 2, explanation: "A revolução derrubou a ordem escravista e colonial francesa, culminando na independência do Haiti em 1804.", year: null, examQuestion: null },
  // Novas questões autorais — Geografia
  { id: "geo-f-2", subject: "geografia", category: "GEOGRAFIA", difficulty: "facil", text: "Para localizar cidades em diferentes partes do globo, a cartografia utiliza linhas imaginárias traçadas sobre o planeta. Uma dessas coordenadas é medida em graus ao norte ou ao sul de uma linha de referência que divide a Terra em hemisférios. Em relação a qual linha a latitude é medida?", options: ["à Linha do Equador", "ao Meridiano de Greenwich", "ao Trópico de Capricórnio apenas", "ao nível médio do mar"], correct: 0, explanation: "A latitude é medida ao norte ou ao sul da Linha do Equador.", year: null, examQuestion: null },
  { id: "geo-m-2", subject: "geografia", category: "GEOGRAFIA", difficulty: "medio", text: "Em um bairro com muitas superfícies asfaltadas, a prefeitura planeja ampliar praças arborizadas e jardins permeáveis. Além de oferecer sombra, a vegetação interfere nas trocas de calor e permite maior infiltração da água da chuva no solo. Qual efeito urbano é esperado com essa intervenção?", options: ["intensificar as ilhas de calor", "reduzir temperaturas locais e ampliar a infiltração da água", "eliminar a necessidade de saneamento", "impedir toda forma de enchente"], correct: 1, explanation: "A vegetação oferece sombra, evapotranspiração e superfícies permeáveis, ajudando a amenizar calor e escoamento superficial.", year: null, examQuestion: null },
  { id: "geo-d-2", subject: "geografia", category: "GEOGRAFIA", difficulty: "dificil", text: "Uma mesma onda de calor ou enchente pode atingir bairros diferentes, mas os efeitos variam conforme moradia, renda, infraestrutura e acesso a serviços. Pesquisadores usam a noção de justiça climática para analisar essas desigualdades e a responsabilidade por enfrentá-las. Qual afirmação está de acordo com essa perspectiva?", options: ["são idênticos para todos os grupos sociais", "atingem apenas áreas rurais", "distribuem-se de forma desigual e afetam mais grupos vulneráveis", "dependem exclusivamente da latitude"], correct: 2, explanation: "A exposição e a capacidade de adaptação variam; comunidades com menos recursos tendem a sofrer impactos mais intensos.", year: null, examQuestion: null },
  // Novas questões autorais — Educação Física
  { id: "edf-f-2", subject: "educacao-fisica", category: "EDUCAÇÃO FÍSICA", difficulty: "facil", text: "Antes de uma aula com corrida e jogos, a professora orienta movimentos leves e progressivos, realizados sem desconforto e por alguns minutos. Essa etapa não substitui a atividade principal nem deve levar à exaustão. Qual é uma finalidade comum do aquecimento?", options: ["cansar o corpo antes do exercício", "substituir a hidratação", "preparar gradualmente o organismo para o esforço", "impedir o aumento da circulação"], correct: 2, explanation: "O aquecimento eleva gradualmente a atividade corporal e prepara para o esforço que virá.", year: null, examQuestion: null },
  { id: "edf-m-2", subject: "educacao-fisica", category: "EDUCAÇÃO FÍSICA", difficulty: "medio", text: "Durante uma partida oficial de futsal, cada equipe organiza seus atletas dentro da quadra conforme a função de cada um, incluindo a pessoa responsável por defender o gol. No início do jogo, quantos jogadores de uma equipe permanecem em quadra, contando o goleiro?", options: ["4", "6", "5", "7"], correct: 2, explanation: "Cada equipe joga com cinco atletas em quadra, incluindo o goleiro.", year: null, examQuestion: null },
  { id: "edf-d-2", subject: "educacao-fisica", category: "EDUCAÇÃO FÍSICA", difficulty: "dificil", text: "Uma pessoa interrompe por várias semanas um programa de treinamento que vinha realizando regularmente. Com o tempo, parte das adaptações fisiológicas e do desempenho anteriormente conquistados pode diminuir, especialmente se não houver estímulos equivalentes. Como se chama esse princípio do treinamento?", options: ["especificidade", "reversibilidade", "individualidade biológica", "sobrecarga"], correct: 1, explanation: "Pelo princípio da reversibilidade, parte das adaptações obtidas pode regredir com a interrupção dos estímulos.", year: null, examQuestion: null },
  // Novas questões autorais — Interdisciplinar
  { id: "int-f-2", subject: "interdisciplinar", category: "INTERDISCIPLINAR", difficulty: "facil", text: "Em uma campanha de coleta seletiva, os estudantes separam papel, plástico e metal antes de encaminhar os materiais aos pontos de reciclagem. A organização por tipo reduz a mistura de resíduos e facilita etapas posteriores de tratamento. Qual contribuição direta essa ação oferece?", options: ["aumentar o descarte irregular", "reduzir o reaproveitamento de materiais", "facilitar a destinação e o reaproveitamento de resíduos", "impedir a coleta seletiva"], correct: 2, explanation: "A separação adequada facilita a coleta seletiva e permite que materiais sejam reaproveitados.", year: null, examQuestion: null },
  { id: "mat-f-3", subject: "matematica", category: "MATEMÁTICA", difficulty: "facil", text: "Uma equipe vai preparar bebidas para uma atividade escolar e utiliza uma garrafa com capacidade de 2 litros. Para registrar o volume em uma planilha que usa mililitros, é necessário converter a unidade antes de preencher os dados. Quantos mililitros cabem nessa garrafa?", options: ["200 mL", "1.000 mL", "2.000 mL", "20.000 mL"], correct: 2, explanation: "Cada litro equivale a 1.000 mL; portanto, 2 L = 2.000 mL.", year: null, examQuestion: null },
  { id: "fis-f-3", subject: "fisica", category: "FÍSICA", difficulty: "facil", text: "Um aparelho utilizado em uma demonstração é ligado a uma fonte de 10 V e, durante seu funcionamento, percorre por ele uma corrente elétrica de 2 A. Considerando essas medidas constantes, qual potência elétrica o aparelho consome?", options: ["5 W", "12 W", "20 W", "100 W"], correct: 2, explanation: "A potência elétrica é P=U·i=10×2=20 W.", year: null, examQuestion: null },
  { id: "int-m-2", subject: "interdisciplinar", category: "INTERDISCIPLINAR", difficulty: "medio", text: "Uma escola organiza uma excursão para 105 estudantes e precisa contratar ônibus com capacidade máxima de 42 passageiros cada. Todos devem viajar sentados e não é permitido exceder a lotação. Qual é o menor número de ônibus necessário para transportar o grupo?", options: ["2", "2,5", "3", "4"], correct: 2, explanation: "105 ÷ 42 = 2,5; como não é possível usar meio ônibus, são necessários 3 ônibus.", year: null, examQuestion: null },
  { id: "int-d-2", subject: "interdisciplinar", category: "INTERDISCIPLINAR", difficulty: "dificil", text: "Uma comunidade com 200 moradores registrou consumo total de 1.500 m³ de água em determinado mês. Para comparar esse dado com outros bairros, a equipe calcula uma média simples por pessoa, supondo que o total seja distribuído igualmente entre todos os moradores. Qual é esse consumo médio mensal individual?", options: ["0,75 m³", "5 m³", "7,5 m³", "75 m³"], correct: 2, explanation: "O consumo médio é 1.500 ÷ 200 = 7,5 m³ por pessoa no mês.", year: null, examQuestion: null },
  // Questões autorais contextualizadas, alinhadas às áreas e habilidades do ENEM.
  { id: "mat-f-4", subject: "matematica", category: "MATEMÁTICA", difficulty: "facil", text: "Uma associação vai comprar camisetas para uma caminhada. Cada unidade custa R$ 40, mas a loja oferece desconto de 15% no pagamento à vista. Sem incluir outras taxas, qual será o valor de uma camiseta com o desconto aplicado?", options: ["R$ 6", "R$ 34", "R$ 35", "R$ 46"], correct: 1, explanation: "O desconto é 0,15 × 40 = R$ 6. Subtraindo do preço original, 40 − 6 = R$ 34.", year: null, examQuestion: null },
  { id: "mat-m-3", subject: "matematica", category: "MATEMÁTICA", difficulty: "medio", text: "Para chegar à escola, uma estudante percorre 12 km de ônibus e depois caminha 1,5 km. Em cinco dias, ela faz esse trajeto completo uma vez por dia. Considerando a mesma distância na volta, quantos quilômetros ela percorre ao todo durante a semana?", options: ["67,5 km", "120 km", "135 km", "150 km"], correct: 2, explanation: "Cada trecho de ida soma 12 + 1,5 = 13,5 km. Ida e volta são 27 km por dia; em cinco dias, 27 × 5 = 135 km.", year: null, examQuestion: null },
  { id: "mat-d-3", subject: "matematica", category: "MATEMÁTICA", difficulty: "dificil", text: "Uma escola compara dois planos para uma visita: o plano A cobra R$ 18 por estudante, enquanto o plano B cobra uma taxa fixa de R$ 120 mais R$ 12 por estudante. A partir de quantos estudantes o plano B passa a custar menos que o plano A? Considere apenas números inteiros de estudantes.", options: ["20", "21", "22", "23"], correct: 1, explanation: "Para o plano B ser mais barato: 120 + 12n < 18n, então n > 20. O menor inteiro que atende à condição é 21. Com 21 estudantes, B custa R$ 372 e A custa R$ 378.", year: null, examQuestion: null },
  { id: "fis-f-4", subject: "fisica", category: "FÍSICA", difficulty: "facil", text: "Em uma aula de mobilidade, um ciclista mantém ritmo constante e percorre 9 km em meia hora. Para comparar esse deslocamento com outros trajetos, a turma calcula a velocidade média usando distância dividida pelo tempo. Qual é o resultado em km/h?", options: ["4,5 km/h", "9 km/h", "18 km/h", "27 km/h"], correct: 2, explanation: "Meia hora corresponde a 0,5 h. A velocidade média é 9 ÷ 0,5 = 18 km/h.", year: null, examQuestion: null },
  { id: "fis-m-3", subject: "fisica", category: "FÍSICA", difficulty: "medio", text: "Uma escola substitui 10 lâmpadas de 60 W por modelos de 9 W. Elas ficam acesas, em média, 5 horas por dia durante 30 dias. Considerando a redução de potência de cada lâmpada e desconsiderando perdas, quanta energia elétrica deixa de ser consumida nesse período?", options: ["7,65 kWh", "76,5 kWh", "765 kWh", "7.650 kWh"], correct: 1, explanation: "A redução total de potência é 10 × (60 − 9) = 510 W = 0,51 kW. O tempo é 5 × 30 = 150 h. A economia é 0,51 × 150 = 76,5 kWh.", year: null, examQuestion: null },
  { id: "fis-d-3", subject: "fisica", category: "FÍSICA", difficulty: "dificil", text: "Em um circuito simples, um resistor de 4 Ω e outro de 8 Ω são ligados em série a uma fonte ideal de 24 V. Para prever o aquecimento, uma estudante calcula primeiro a resistência equivalente e depois usa a relação entre tensão e resistência. Qual corrente percorre o circuito?", options: ["1 A", "2 A", "3 A", "6 A"], correct: 1, explanation: "Em série, a resistência equivalente é 4 + 8 = 12 Ω. Pela lei de Ohm, I = V/R = 24/12 = 2 A.", year: null, examQuestion: null },
  { id: "qui-f-3", subject: "quimica", category: "QUÍMICA", difficulty: "facil", text: "Uma equipe prepara uma solução dissolvendo 10 g de sal em água e completando o volume final para 500 mL. Para comparar receitas, precisa expressar a concentração comum em gramas por litro. Qual é a concentração dessa solução?", options: ["5 g/L", "10 g/L", "20 g/L", "50 g/L"], correct: 2, explanation: "500 mL correspondem a 0,5 L. A concentração é 10 g ÷ 0,5 L = 20 g/L.", year: null, examQuestion: null },
  { id: "qui-m-3", subject: "quimica", category: "QUÍMICA", difficulty: "medio", text: "Em uma atividade sobre qualidade da água, uma amostra de 200 mL contém 4 mg de determinada substância dissolvida. Supondo distribuição uniforme e sem alteração da concentração, quantos miligramas dessa substância estariam presentes em 1 litro da mesma água?", options: ["8 mg", "16 mg", "20 mg", "40 mg"], correct: 2, explanation: "Um litro tem cinco vezes o volume de 200 mL. Mantida a concentração, a massa também é multiplicada por cinco: 4 × 5 = 20 mg.", year: null, examQuestion: null },
  { id: "qui-d-3", subject: "quimica", category: "QUÍMICA", difficulty: "dificil", text: "Uma reação de neutralização pode ser representada por HCl + NaOH → NaCl + H₂O. Um experimento usa 0,20 mol de HCl e 0,15 mol de NaOH, em proporção estequiométrica de 1:1. Qual reagente limita a reação e quantos mols de água podem ser formados, considerando conversão completa?", options: ["HCl; 0,15 mol", "NaOH; 0,15 mol", "NaOH; 0,20 mol", "HCl; 0,35 mol"], correct: 1, explanation: "A proporção é 1:1 e há menos NaOH. Ele é o reagente limitante, formando no máximo 0,15 mol de água.", year: null, examQuestion: null },
  { id: "bio-f-3", subject: "biologia", category: "BIOLOGIA", difficulty: "facil", text: "Em uma horta escolar, plantas recebem luz, água e gás carbônico e produzem matéria orgânica, liberando oxigênio. A turma relaciona esse processo à entrada de energia na cadeia alimentar. Qual processo biológico está sendo observado?", options: ["Fermentação", "Fotossíntese", "Respiração anaeróbica", "Digestão extracelular"], correct: 1, explanation: "Na fotossíntese, organismos produtores usam energia luminosa para sintetizar matéria orgânica a partir de água e dióxido de carbono, liberando oxigênio.", year: null, examQuestion: null },
  { id: "bio-m-3", subject: "biologia", category: "BIOLOGIA", difficulty: "medio", text: "Após a aplicação de um inseticida, a maioria dos insetos de uma população morre, mas alguns indivíduos já possuíam uma característica hereditária que reduz a sensibilidade ao produto. Se o uso continuar por várias gerações, qual mudança é mais provável na população?", options: ["A resistência surge por necessidade em todos os indivíduos", "A frequência de indivíduos resistentes tende a aumentar", "Todos os insetos passam a ser geneticamente idênticos", "O inseticida transforma diretamente cada indivíduo resistente"], correct: 1, explanation: "A seleção natural favorece indivíduos que já apresentam variação hereditária vantajosa; eles tendem a deixar mais descendentes, elevando a frequência da resistência.", year: null, examQuestion: null },
  { id: "bio-d-3", subject: "biologia", category: "BIOLOGIA", difficulty: "dificil", text: "Em um lago, a entrada excessiva de fertilizantes aumenta a disponibilidade de nutrientes e favorece uma floração de algas. Depois, a decomposição dessa biomassa reduz o oxigênio dissolvido, causando morte de peixes. Qual cadeia de processos explica melhor o fenômeno?", options: ["Eutrofização, decomposição intensa e hipóxia", "Desertificação, fotólise e aumento de oxigênio", "Magnificação trófica, salinização e acidificação", "Sucessão primária, nitrificação e congelamento"], correct: 0, explanation: "O enriquecimento por nutrientes provoca eutrofização e crescimento de algas; a decomposição consome oxigênio da água e pode causar hipóxia, prejudicando organismos aquáticos.", year: null, examQuestion: null },
  { id: "fil-f-3", subject: "filosofia", category: "FILOSOFIA", difficulty: "facil", text: "Em uma reunião, uma estudante discorda de uma regra e apresenta razões, escuta objeções e revisa sua posição quando encontra evidências melhores. Qual atitude filosófica aparece com mais clareza nessa situação?", options: ["Aceitação dogmática", "Investigação crítica", "Apelo exclusivo à tradição", "Relativismo sem argumentos"], correct: 1, explanation: "A investigação crítica examina razões, considera objeções e admite revisar conclusões diante de argumentos ou evidências.", year: null, examQuestion: null },
  { id: "fil-m-3", subject: "filosofia", category: "FILOSOFIA", difficulty: "medio", text: "Uma política pública melhora a situação da maioria, mas impõe um prejuízo grave a um pequeno grupo. Uma análise utilitarista tende a avaliar a ação principalmente pelo saldo de consequências para o bem-estar, enquanto uma ética de deveres também pergunta se direitos foram respeitados. Qual contraste está corretamente expresso?", options: ["As duas abordagens ignoram consequências", "O utilitarismo considera consequências; a ética de deveres também avalia princípios e direitos", "A ética de deveres decide somente pela maioria", "O utilitarismo rejeita qualquer cálculo de efeitos"], correct: 1, explanation: "O utilitarismo dá centralidade às consequências agregadas; teorias de deveres examinam obrigações e limites morais que não se reduzem ao saldo de benefícios.", year: null, examQuestion: null },
  { id: "fil-d-3", subject: "filosofia", category: "FILOSOFIA", difficulty: "dificil", text: "Uma pessoa defende que todos devem cumprir uma promessa, mas abre uma exceção para si sempre que descumpri-la lhe traz vantagem. Ao testar essa máxima pela proposta kantiana, deve-se perguntar se ela pode ser universalizada sem comprometer a própria prática de prometer. Qual problema aparece nesse teste?", options: ["A máxima se torna uma lei natural", "A universalização enfraquece a confiança que torna promessas possíveis", "A ação passa a ser correta por gerar lucro", "A intenção deixa de ter importância"], correct: 1, explanation: "Se todos pudessem descumprir promessas quando lhes convém, a confiança e a própria prática social de prometer seriam comprometidas, gerando contradição na universalização da máxima.", year: null, examQuestion: null },
  { id: "his-f-3", subject: "historia", category: "HISTÓRIA", difficulty: "facil", text: "Em uma linha do tempo sobre o Brasil, a turma precisa ordenar três marcos: chegada da corte portuguesa, Independência e abolição legal da escravidão. Qual sequência apresenta esses acontecimentos do mais antigo para o mais recente?", options: ["Independência, chegada da corte, abolição", "Chegada da corte, Independência, abolição", "Abolição, Independência, chegada da corte", "Chegada da corte, abolição, Independência"], correct: 1, explanation: "A corte portuguesa chegou em 1808, a Independência foi proclamada em 1822 e a Lei Áurea aboliu legalmente a escravidão em 1888.", year: null, examQuestion: null },
  { id: "his-m-3", subject: "historia", category: "HISTÓRIA", difficulty: "medio", text: "Dois relatos sobre uma greve do início do século XX descrevem o mesmo episódio de modos diferentes: um jornal empresarial enfatiza prejuízos à produção; um depoimento de trabalhador destaca jornadas e salários. O que a comparação dessas fontes permite ao historiador perceber?", options: ["Que uma fonte elimina a necessidade de analisar a outra", "Que os relatos refletem perspectivas e interesses distintos", "Que depoimentos pessoais não podem ser fontes", "Que todo conflito teve uma única causa"], correct: 1, explanation: "Fontes são produzidas em contextos e posições sociais específicos. Compará-las ajuda a identificar perspectivas, interesses e limites de cada relato.", year: null, examQuestion: null },
  { id: "his-d-3", subject: "historia", category: "HISTÓRIA", difficulty: "dificil", text: "A abolição da escravidão no Brasil, em 1888, encerrou juridicamente a condição escravista, mas não foi acompanhada por políticas amplas de acesso à terra, educação e trabalho protegido para a população liberta. Que interpretação histórica considera simultaneamente a mudança legal e seus limites sociais?", options: ["A lei eliminou imediatamente todas as desigualdades", "A abolição foi uma ruptura legal importante, sem garantir inclusão socioeconômica", "A escravidão continuou legalmente até a República", "A mudança não alterou nenhuma relação social"], correct: 1, explanation: "A abolição extinguiu a legalidade da escravidão, mas a ausência de medidas de integração manteve e reorganizou desigualdades raciais e econômicas.", year: null, examQuestion: null },
  { id: "geo-f-3", subject: "geografia", category: "GEOGRAFIA", difficulty: "facil", text: "Em um mapa turístico, 1 cm representa 2 km no terreno. A distância entre duas praças mede 3,5 cm no papel. Desconsiderando curvas do percurso e diferenças de relevo, qual é a distância em linha reta entre elas?", options: ["5,5 km", "6 km", "7 km", "8 km"], correct: 2, explanation: "Cada centímetro equivale a 2 km. Logo, 3,5 × 2 = 7 km.", year: null, examQuestion: null },
  { id: "geo-m-3", subject: "geografia", category: "GEOGRAFIA", difficulty: "medio", text: "Dois bairros têm a mesma população, mas um concentra moradores em área menor e dispõe de menos linhas de ônibus, postos de saúde e áreas verdes. Para analisar desigualdade urbana, não basta comparar habitantes: também é necessário considerar distribuição territorial e acesso a serviços. Qual conceito ajuda a interpretar essa situação?", options: ["Segregação socioespacial", "Transição demográfica", "Intemperismo químico", "Êxodo rural histórico"], correct: 0, explanation: "A segregação socioespacial expressa a distribuição desigual de grupos, infraestrutura e oportunidades no espaço urbano.", year: null, examQuestion: null },
  { id: "geo-d-3", subject: "geografia", category: "GEOGRAFIA", difficulty: "dificil", text: "Uma cidade registra enchentes mais frequentes após substituir áreas permeáveis por ruas e estacionamentos, enquanto bairros de menor renda ocupam margens de córregos e têm drenagem precária. Qual análise integra adequadamente o processo ambiental e a desigualdade territorial?", options: ["A impermeabilização aumenta o escoamento, e a vulnerabilidade depende também da infraestrutura e da localização", "A chuva explica sozinha todos os danos, independentemente do uso do solo", "A urbanização impede a infiltração e elimina diferenças sociais", "A localização dos bairros não interfere na exposição a riscos"], correct: 0, explanation: "A impermeabilização pode intensificar o escoamento superficial; ocupação de áreas de risco, infraestrutura desigual e capacidade de resposta distribuem os impactos de forma desigual.", year: null, examQuestion: null },
  { id: "edf-f-3", subject: "educacao-fisica", category: "EDUCAÇÃO FÍSICA", difficulty: "facil", text: "Antes de uma caminhada em grupo, a professora propõe alguns minutos de movimentos leves e progressivos. A atividade não deve causar exaustão; sua função é preparar o corpo para o esforço que virá. Qual é o objetivo principal desse aquecimento?", options: ["Substituir a atividade principal", "Preparar gradualmente o organismo para o exercício", "Evitar qualquer aumento da circulação", "Garantir que ninguém precise beber água"], correct: 1, explanation: "O aquecimento eleva gradualmente a atividade corporal e prepara músculos e sistemas envolvidos no esforço, sem substituir a atividade principal.", year: null, examQuestion: null },
  { id: "edf-m-3", subject: "educacao-fisica", category: "EDUCAÇÃO FÍSICA", difficulty: "medio", text: "Em uma aula de jogos, estudantes têm diferentes experiências motoras e necessidades de acessibilidade. A turma adapta o tamanho da área, oferece materiais com características variadas e combina regras para que todos participem com segurança, sem retirar o objetivo de cooperação. Qual princípio pedagógico orienta essas decisões?", options: ["Seleção dos mais habilidosos", "Inclusão com adaptação e equidade", "Padronização obrigatória do desempenho", "Eliminação da participação coletiva"], correct: 1, explanation: "A inclusão busca remover barreiras e ajustar condições para que diferentes estudantes participem de maneira significativa e equitativa.", year: null, examQuestion: null },
  { id: "edf-d-3", subject: "educacao-fisica", category: "EDUCAÇÃO FÍSICA", difficulty: "dificil", text: "Uma pessoa inicia um programa de corrida, aumenta rapidamente a distância e passa a sentir dor persistente. O planejamento responsável considera progressão gradual, descanso, especificidade e diferenças individuais, além de interromper o esforço quando há sinais de lesão. Qual decisão é mais adequada?", options: ["Aumentar ainda mais a carga para acelerar a adaptação", "Manter a dor como critério de progresso", "Reduzir ou interromper o esforço e reavaliar a carga com orientação adequada", "Eliminar todos os períodos de recuperação"], correct: 2, explanation: "A progressão deve respeitar a resposta individual e a recuperação. Dor persistente exige reduzir ou suspender o estímulo e buscar avaliação apropriada, em vez de insistir na sobrecarga.", year: null, examQuestion: null },
  { id: "int-f-3", subject: "interdisciplinar", category: "INTERDISCIPLINAR", difficulty: "facil", text: "Uma turma recolheu 18 kg de papel em uma campanha e separou o material em três caixas com a mesma quantidade. Para registrar a contribuição de cada grupo, os estudantes dividem o total igualmente. Quantos quilogramas ficam em cada caixa?", options: ["3 kg", "6 kg", "9 kg", "15 kg"], correct: 1, explanation: "A divisão é 18 ÷ 3 = 6 kg por caixa.", year: null, examQuestion: null },
  { id: "int-m-3", subject: "interdisciplinar", category: "INTERDISCIPLINAR", difficulty: "medio", text: "Uma escola mede o consumo de água antes e depois de uma campanha: a média diária cai de 2.400 litros para 1.920 litros. Para avaliar o resultado, a equipe compara a redução com o valor inicial, e não com o valor final. Qual foi a redução percentual?", options: ["15%", "20%", "25%", "30%"], correct: 1, explanation: "A redução foi 2.400 − 1.920 = 480 L. Em relação ao valor inicial: 480 ÷ 2.400 = 0,20, ou 20%.", year: null, examQuestion: null },
  { id: "int-d-3", subject: "interdisciplinar", category: "INTERDISCIPLINAR", difficulty: "dificil", text: "Uma praça de 10.000 m² será parcialmente arborizada. O projeto prevê ampliar a cobertura vegetal de 20% para 35% da área, sem alterar o tamanho total da praça. Quantos metros quadrados adicionais de vegetação são necessários para atingir a meta?", options: ["500 m²", "1.000 m²", "1.500 m²", "3.500 m²"], correct: 2, explanation: "O aumento é de 35% − 20% = 15% da área. 0,15 × 10.000 = 1.500 m² adicionais.", year: null, examQuestion: null }
];
